func newBankReceipt() unsafe.Pointer { return unsafe.Pointer(new(bankreceipt.BankReceipt)) }

func newNBankReceipt(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]bankreceipt.BankReceipt, n)))
}

func ptrBankReceipt(p unsafe.Pointer, c int32) any {
	r := (*bankreceipt.BankReceipt)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return &r.ReceiptDate
	case 4:
		return &r.AmountMinor
	case 5:
		return &r.ReferenceNumber
	case 6:
		return &r.Memo
	case 7:
		return (*string)(unsafe.Pointer(&r.Status))
	case 8:
		return (*string)(unsafe.Pointer(&r.ImportBatchID))
	case 9:
		return (*string)(unsafe.Pointer(&r.MatchedCustomerPaymentID))
	case 10:
		return &r.MatchedAt
	case 11:
		return (*string)(unsafe.Pointer(&r.MatchedByID))
	case 12:
		return &r.ExceptionReason
	case 13:
		return (*string)(unsafe.Pointer(&r.CreatedByID))
	case 14:
		return (*string)(unsafe.Pointer(&r.UpdatedByID))
	case 15:
		return &r.Version
	case 16:
		return &r.CreatedAt
	case 17:
		return &r.UpdatedAt
	}
	return nil
}

func valueBankReceipt(p unsafe.Pointer, c int32) any {
	r := (*bankreceipt.BankReceipt)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return r.ReceiptDate
	case 4:
		return r.AmountMinor
	case 5:
		if r.ReferenceNumber == "" {
			return nil
		}
		return r.ReferenceNumber
	case 6:
		if r.Memo == "" {
			return nil
		}
		return r.Memo
	case 7:
		return string(r.Status)
	case 8:
		if r.ImportBatchID == "" {
			return nil
		}
		return string(r.ImportBatchID)
	case 9:
		if r.MatchedCustomerPaymentID == "" {
			return nil
		}
		return string(r.MatchedCustomerPaymentID)
	case 10:
		if r.MatchedAt == nil {
			return nil
		}
		return *r.MatchedAt
	case 11:
		if r.MatchedByID == "" {
			return nil
		}
		return string(r.MatchedByID)
	case 12:
		if r.ExceptionReason == "" {
			return nil
		}
		return r.ExceptionReason
	case 13:
		return string(r.CreatedByID)
	case 14:
		if r.UpdatedByID == "" {
			return nil
		}
		return string(r.UpdatedByID)
	case 15:
		return r.Version
	case 16:
		return r.CreatedAt
	case 17:
		return r.UpdatedAt
	}
	return nil
}

func attachBankReceipt(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*bankreceipt.BankReceipt)(p)
	switch rel {
	case 0:
		r.MatchedCustomerPayment = (*customerpayment.Payment)(child)
	}
}

